import math
import sys

eps = 1e-6
PI = math.acos(-1.0)
EPS = eps
pi = PI
N = int(1e2 + 10)


class Point:
    def __init__(self, x=0.0, y=0.0):
        if isinstance(x, Point):
            self.x = x.x
            self.y = x.y
        else:
            self.x = x
            self.y = y

    def set(self, x, y):
        self.x = x
        self.y = y

    def read(self):
        self.x, self.y = map(float, sys.stdin.readline().split())

    def print(self, end_str=""):
        print(f"{self.x:.6f} {self.y:.6f}{end_str}", end="")

    def rot90(self):
        return Point(-self.y, self.x)

    def __add__(self, other):
        return Point(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Point(self.x - other.x, self.y - other.y)

    def __mul__(self, val):
        return Point(self.x * val, self.y * val)

    def __truediv__(self, val):
        return self * (1.0 / val)

    def __repr__(self):
        x = 0 if abs(self.x - 0) < eps else self.x
        y = 0 if abs(self.y - 0) < eps else self.y
        return f"({x},{y})"


Vec = Point


def PtoV(a, b):
    return Vec(b.x - a.x, b.y - a.y)


def dMult(a, b):
    return a.x * b.x + a.y * b.y


def xMult(a, b):
    return a.x * b.y - a.y * b.x


def VecMod(a):
    return math.sqrt(dMult(a, a))


def VecMod2(a):
    return dMult(a, a)


def Corner2V(a, b):
    return abs(math.acos(dMult(a, b) / VecMod(a) / VecMod(b)))


def VecUnit(a):
    return a / VecMod(a)


def VRotate(v, alph):
    sa = math.sin(alph)
    ca = math.cos(alph)
    return Vec(v.x * ca - v.y * sa, v.x * sa + v.y * ca)


def PRotate(p, o, alph):
    return Point(o + VRotate(PtoV(o, p), alph))


def GetVV(v):
    return VRotate(v, pi / 2)


def ShadowPOnLine(p, a, b):
    ab = PtoV(a, b)
    ap = PtoV(a, p)
    alph = VecUnit(ab) * dMult(ab, ap) / VecMod(ab)
    return a + alph


def LineCrossCircle(a, b, o, r):
    ret = []
    t = ShadowPOnLine(o, a, b)
    ot = PtoV(o, t)
    if VecMod(ot) - r > eps:
        return ret
    if abs(VecMod(ot) - r) < eps:
        ret.append(t)
        return ret
    lr = math.sqrt(r * r - VecMod2(ot))
    ta = t + VecUnit(PtoV(t, a)) * lr
    tb = t + VecUnit(PtoV(t, b)) * lr
    ret.append(ta)
    ret.append(tb)
    return ret


def PointTangentCircle(p, o, r):
    x2 = VecMod2(p - o)
    d2 = x2 - r * r
    ret = []
    if d2 < -eps:
        return ret
    if r <= eps:
        ret.append(o)
        ret.append(o)
        return ret
    d2 = max(d2, 0.0)
    q1 = o + (p - o) * (r * r / x2)
    q2 = (p - o).rot90() * (-r * math.sqrt(d2) / x2)
    ret.append(q1 - q2)
    ret.append(q1 + q2)
    return ret


def POnSeg(p, a, b):
    if abs(xMult(PtoV(a, b), PtoV(a, p))) > eps:
        return False
    if min(a.x, b.x) > p.x or p.x > max(a.x, b.x):
        return False
    if min(a.y, b.y) > p.y or p.y > max(a.y, b.y):
        return False
    return True


def PDisLine(p, a, b):
    return VecMod(ShadowPOnLine(p, a, b) - p)


p = Point()
s = Point()
vp = 0.0
vs = 0.0
r = 0.0
sita = 0.0


def check(t):
    len_or = VecMod(p)
    e = Point(len_or * math.cos(sita + t * vp / len_or),
              len_or * math.sin(sita + t * vp / len_or))
    ccp = LineCrossCircle(s, e, Point(0, 0), r)
    if len(ccp) != 2 or (not POnSeg(ccp[0], s, e) and not POnSeg(ccp[1], s, e)):
        return vs * t > VecMod(e - s)
    ttp1 = PointTangentCircle(s, Point(0, 0), r)
    if PDisLine(ttp1[0], s, e) > PDisLine(ttp1[1], s, e):
        ttp1[0], ttp1[1] = ttp1[1], ttp1[0]
    l1 = VecMod(PtoV(s, ttp1[0]))
    ttp2 = PointTangentCircle(e, Point(0, 0), r)
    if PDisLine(ttp2[0], s, e) > PDisLine(ttp2[1], s, e):
        ttp2[0], ttp2[1] = ttp2[1], ttp2[0]
    l2 = VecMod(PtoV(e, ttp2[0]))
    alph = Corner2V(PtoV(Point(0, 0), ttp1[0]), PtoV(Point(0, 0), ttp2[0]))
    return VecMod(PtoV(s, ttp1[0])) + VecMod(PtoV(e, ttp2[0])) + alph * r < vs * t


def main():
    global p, s, vp, vs, r, sita
    data = sys.stdin.read().strip().split()
    it = iter(data)
    out_lines = []
    for _ in range(10**18):
        try:
            px = float(next(it))
            py = float(next(it))
            p = Point(px, py)
            vp = float(next(it))
            sx = float(next(it))
            sy = float(next(it))
            s = Point(sx, sy)
            vs = float(next(it))
            r = float(next(it))
        except StopIteration:
            break
        sita = math.acos(p.x / VecMod(p))
        if p.y < 0:
            sita = -sita
        left = 0.0
        right = 1e10
        while abs(left - right) > 1e-12:
            mid = (left + right) * 0.5
            if check(mid):
                right = mid
            else:
                left = mid
        out_lines.append(f"{left:.9f}")
    sys.stdout.write("\n".join(out_lines))


if __name__ == "__main__":
    main()

